using AeroCompliance.ApiService.Authorization; using AeroCompliance.ApiService.Services; using AeroCompliance.Contracts.Dtos.Common; using AeroCompliance.Contracts.Dtos.Gis; using AeroCompliance.Domain.Entities; using AeroCompliance.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AeroCompliance.ApiService.Controllers;
[ApiController, Route("api/blocks"), Authorize]
public sealed class BlocksController(AeroComplianceDbContext db, ICurrentUserContext user, IAuditService audit) : ControllerBase
{
    [HttpGet] public async Task<ActionResult<PagedResponse<BlockDto>>> List(int page=1,int pageSize=25,Guid? zoneId=null,string? search=null,CancellationToken ct=default)
    { if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination"); IQueryable<Block> q=Visible().AsNoTracking().Include(x=>x.Zone); if(zoneId.HasValue)q=q.Where(x=>x.ZoneId==zoneId);var s=ApiSupport.NormalizeSearch(search);if(s is not null)q=q.Where(x=>x.BlockNumber.ToLower().Contains(s));var total=await q.CountAsync(ct);var rows=await q.OrderBy(x=>x.BlockNumber).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);return Ok(new PagedResponse<BlockDto>(rows.Select(Map).ToList(),page,pageSize,total,total==0?0:(int)Math.Ceiling(total/(double)pageSize)));}
    [HttpGet("{id:guid}")] public async Task<ActionResult<BlockDto>> Get(Guid id,CancellationToken ct){var x=await Visible().AsNoTracking().Include(x=>x.Zone).SingleOrDefaultAsync(x=>x.Id==id,ct);return x is null?NotFound():Ok(Map(x));}
    [HttpPost,Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<BlockDto>> Create(SaveBlockRequest r,CancellationToken ct){if(!await VisibleZones().AnyAsync(x=>x.Id==r.ZoneId,ct))return NotFound();if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var n=r.BlockNumber.Trim();if(await db.Blocks.AnyAsync(x=>x.ZoneId==r.ZoneId&&x.BlockNumber==n,ct))return Problem(statusCode:409,title:"Conflict",detail:"Block number already exists in this zone.");var x=new Block{Id=Guid.NewGuid(),ZoneId=r.ZoneId,BlockNumber=n,Geom=g,CreatedAt=DateTimeOffset.UtcNow};db.Blocks.Add(x);audit.Add("block.create","Block",x.Id,after:new{x.ZoneId,x.BlockNumber});await db.SaveChangesAsync(ct);await db.Entry(x).Reference(b=>b.Zone).LoadAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},Map(x));}
    [HttpPut("{id:guid}"),Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<BlockDto>> Update(Guid id,SaveBlockRequest r,CancellationToken ct){var x=await Visible().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();var zone=await VisibleZones().SingleOrDefaultAsync(z=>z.Id==r.ZoneId,ct);if(zone is null)return NotFound();if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var n=r.BlockNumber.Trim();if(await db.Blocks.AnyAsync(b=>b.Id!=id&&b.ZoneId==r.ZoneId&&b.BlockNumber==n,ct))return Problem(statusCode:409,title:"Conflict",detail:"Block number already exists in this zone.");var before=new{x.ZoneId,x.BlockNumber};x.ZoneId=r.ZoneId;x.Zone=zone;x.BlockNumber=n;x.Geom=g;audit.Add("block.update","Block",id,before,new{x.ZoneId,x.BlockNumber});await db.SaveChangesAsync(ct);return Ok(Map(x));}
    private IQueryable<Block> Visible()=>user.IsPlatformAdmin?db.Blocks:db.Blocks.Where(x=>x.Zone.MunicipalityId==user.MunicipalityId);private IQueryable<Zone> VisibleZones()=>user.IsPlatformAdmin?db.Zones:db.Zones.Where(x=>x.MunicipalityId==user.MunicipalityId);private static BlockDto Map(Block x)=>new(x.Id,x.ZoneId,x.Zone?.ZoneNumber,x.BlockNumber,GeoJsonService.Write(x.Geom),x.CreatedAt);
}
